import { tv, type VariantProps } from "@/lib/beton/tv";

export const bentoGrid = tv({
  slots: {
    list: "grid auto-rows-[minmax(12rem,auto)] gap-4 sm:grid-cols-2 lg:grid-cols-3",
    item: "flex h-full flex-col justify-between gap-4 border-3 border-border bg-raised p-6 shadow-sm",
    itemTitle: "font-display text-h4 font-extrabold text-foreground",
    itemDescription: "text-pretty text-foreground",
    media: "flex min-h-0 flex-1 items-center justify-center",
  },
  variants: {
    span: {
      1: {},
      2: { item: "sm:col-span-2" },
      3: { item: "sm:col-span-2 lg:col-span-3" },
    },
    tall: {
      true: { item: "row-span-2" },
    },
    accent: {
      none: {},
      primary: { item: "bg-primary" },
      secondary: { item: "bg-secondary" },
      ink: { item: "bg-ink text-paper" },
    },
  },
  defaultVariants: {
    span: 1,
    tall: false,
    accent: "none",
  },
});

export type BentoGridVariants = VariantProps<typeof bentoGrid>;

import { bentoGrid, type BentoGridVariants } from "@/lib/beton/recipes/bento-grid.recipe";
import type { ReactNode } from "react";
import { Section, type SectionProps } from "@/components/ui/beton/section";

export interface BentoCell extends Omit<BentoGridVariants, "span"> {
  /** What the cell is called. */
  title: ReactNode;
  /** A line or two under the title. */
  description?: ReactNode;
  /** Anything to show inside: a component, a picture, a number. */
  media?: ReactNode;
  /** How many columns the cell takes. */
  span?: 1 | 2 | 3;
  /** Makes the whole cell a link. */
  href?: string;
}

export interface BentoGridProps extends Omit<SectionProps, "children"> {
  /** The cells, in order. */
  cells: BentoCell[];
  /** The heading level of each cell. One below the section heading. */
  itemHeadingLevel?: 3 | 4 | 5;
  /** Classes for the grid itself. */
  listClassName?: string;
}

/** A grid of boxes of different sizes: the one that gets screenshotted. */
export function BentoGrid({
  cells,
  itemHeadingLevel = 3,
  listClassName,
  ...props
}: BentoGridProps) {
  const Heading = `h${itemHeadingLevel}` as const;
  const list = bentoGrid().list({ class: listClassName });

  return (
    <Section {...props}>
      <ul className={list}>
        {cells.map((cell, index) => {
          const styles = bentoGrid({
            span: cell.span ?? 1,
            tall: cell.tall ?? false,
            accent: cell.accent ?? "none",
          });
          return (
            <li key={index} className={styles.item()}>
              <div>
                <Heading className={styles.itemTitle()}>
                  {cell.href ? <a href={cell.href}>{cell.title}</a> : cell.title}
                </Heading>
                {cell.description ? (
                  <p className={styles.itemDescription()}>{cell.description}</p>
                ) : null}
              </div>
              {cell.media ? <div className={styles.media()}>{cell.media}</div> : null}
            </li>
          );
        })}
      </ul>
    </Section>
  );
}
